// PropertyPage.js
// ------------------------------------------------------
// This component displays:
// - full property details
// - large gallery
// - description, floor plan, and map in tabs
// Security: HTML-encode descriptions to prevent injection
// ------------------------------------------------------

import React from "react";
import { useParams } from "react-router-dom";
import propertiesData from "../data/properties.json";
import Gallery from "../components/Gallery/Gallery";
import Tabs from "../components/Tabs/Tabs";

const PropertyPage = () => {
  const { id } = useParams();

  // Find selected property
  const property = propertiesData.find((p) => p.id === id);

  if (!property) {
    return <h2 style={{ padding: "20px" }}>Property not found</h2>;
  }

  return (
    <div
      style={{
        padding: "20px",
        maxWidth: "900px",
        margin: "0 auto"
      }}
    >
      <h1>
        {property.type} — £{property.price.toLocaleString()}
      </h1>
      <h3>{property.location}</h3>

      {/* Property Gallery */}
      <Gallery images={property.images} />

      {/* Tabs (with security encoding for description) */}
      <Tabs
        description={String(property.longDescription).replace(/</g, "&lt;")}
        floorPlan={property.floorPlan}
        lat={property.lat}
        lng={property.lng}
      />
    </div>
  );
};

export default PropertyPage;
