import React from "react";

const PropertyCard = ({ property }) => {
  return (
    <div
      className="property-card"
      style={{
        border: "1px solid #ddd",
        borderRadius: "12px",
        padding: "15px",
        width: "300px",
        background: "white",
        boxShadow: "0 2px 8px rgba(0,0,0,0.08)",
      }}
    >
      <img
        src={property.images[0]}
        alt={property.shortDescription}
        style={{
          width: "100%",
          height: "180px",
          borderRadius: "12px",
          objectFit: "cover",
        }}
      />

      <h3 style={{ marginTop: "10px", marginBottom: "5px", fontWeight: 600 }}>
        {property.type} — £{property.price.toLocaleString()}
      </h3>

      <p style={{ margin: "5px 0" }}>{property.shortDescription}</p>

      <p style={{ margin: "5px 0" }}>
        <strong>{property.bedrooms} bedrooms</strong>
      </p>

      <p style={{ margin: "5px 0" }}>
        <strong>Postcode:</strong> {property.postcode}
      </p>

      <a
        href={`/property/${property.id}`}
        style={{
          display: "inline-block",
          marginTop: "10px",
          background: "#1976d2",
          padding: "10px 15px",
          color: "white",
          textDecoration: "none",
          borderRadius: "8px",
          fontWeight: "bold",
        }}
      >
        View Property
      </a>
    </div>
  );
};

export default PropertyCard;
