import React, { useState } from "react";

const Tabs = ({ description, floorPlan, lat, lng }) => {
  const [tab, setTab] = useState("description");

  return (
    <div>
      {/* Tab Buttons */}
      <div style={{ display: "flex", gap: "10px", marginBottom: "15px" }}>
        <button
          onClick={() => setTab("description")}
          className={`tab-button ${tab === "description" ? "active" : ""}`}
        >
          Description
        </button>

        <button
          onClick={() => setTab("floorPlan")}
          className={`tab-button ${tab === "floorPlan" ? "active" : ""}`}
        >
          Floor Plan
        </button>

        <button
          onClick={() => setTab("map")}
          className={`tab-button ${tab === "map" ? "active" : ""}`}
        >
          Map
        </button>
      </div>

      {/* Tab Content */}
      {tab === "description" && (
        <p style={{ lineHeight: "1.6" }}>{description}</p>
      )}

      {tab === "floorPlan" && (
        <img
          src={floorPlan}
          alt="Floor Plan"
          style={{
            width: "100%",
            borderRadius: "12px",
            boxShadow: "0 3px 10px rgba(0,0,0,0.15)",
          }}
        />
      )}

      {tab === "map" && (
        <iframe
          title="map"
          width="100%"
          height="300"
          style={{
            border: 0,
            borderRadius: "12px",
            boxShadow: "0 3px 10px rgba(0,0,0,0.15)",
          }}
          loading="lazy"
          src={`https://www.google.com/maps/embed/v1/place?q=${lat},${lng}&key=YOUR_API_KEY_HERE`}
        ></iframe>
      )}
    </div>
  );
};

export default Tabs;
