import React, { useState } from "react";

const Gallery = ({ images }) => {
  const [mainImage, setMainImage] = useState(images[0]);

  return (
    <div style={{ marginBottom: "20px" }}>
      {/* Main Image */}
      <img
        src={mainImage}
        alt="Property"
        className="gallery-main"
        style={{
          width: "100%",
          height: "350px",
          objectFit: "cover",
          borderRadius: "12px",
        }}
      />

      {/* Thumbnails */}
      <div
        style={{
          display: "flex",
          gap: "10px",
          marginTop: "10px",
          overflowX: "auto",
        }}
      >
        {images.map((img, index) => (
          <img
            key={index}
            src={img}
            alt="thumb"
            className="gallery-thumb"
            onClick={() => setMainImage(img)}
            style={{
              width: "90px",
              height: "70px",
              objectFit: "cover",
              borderRadius: "8px",
              border: img === mainImage ? "2px solid #1976d2" : "2px solid transparent",
              cursor: "pointer",
            }}
          />
        ))}
      </div>
    </div>
  );
};

export default Gallery;
