// SearchForm.js
// ------------------------------------------------------
// This component renders the search form using:
// - React Select (dropdowns)
// - MUI text inputs
// - React DatePicker
// It also sanitises numeric inputs for security.
// ------------------------------------------------------

import React, { useState } from "react";
import Select from "react-select";
import DatePicker from "react-datepicker";
import "react-datepicker/dist/react-datepicker.css";
import { TextField, Button } from "@mui/material";

const SearchForm = ({ onSearch }) => {
  // ----------------------------
  // FORM STATE
  // ----------------------------
  const [type, setType] = useState(null);
  const [minPrice, setMinPrice] = useState("");
  const [maxPrice, setMaxPrice] = useState("");
  const [minBedrooms, setMinBedrooms] = useState("");
  const [maxBedrooms, setMaxBedrooms] = useState("");
  const [dateAdded, setDateAdded] = useState(null);
  const [postcode, setPostcode] = useState(null);

  // ----------------------------
  // OPTIONS FOR DROPDOWNS
  // ----------------------------
  const propertyTypes = [
    { value: "Any", label: "Any" },
    { value: "House", label: "House" },
    { value: "Flat", label: "Flat" }
  ];

  const postcodeOptions = [
    { value: "BR1", label: "BR1" },
    { value: "BR2", label: "BR2" },
    { value: "BR3", label: "BR3" },
    { value: "BR5", label: "BR5" },
    { value: "BR6", label: "BR6" },
    { value: "SE3", label: "SE3" },
    { value: "NW1", label: "NW1" }
  ];

  // ----------------------------
  // SECURITY: SANITISE NUMBER INPUTS
  // Only digits allowed.
  // ----------------------------
  const handleNumericInput = (e, setter) => {
    const cleaned = e.target.value.replace(/[^\d]/g, "");
    setter(cleaned);
  };

  // ----------------------------
  // SUBMIT SEARCH FORM
  // ----------------------------
  const handleSubmit = (e) => {
    e.preventDefault();

    onSearch({
      type: type?.value || "",
      minPrice,
      maxPrice,
      minBedrooms,
      maxBedrooms,
      dateAdded,
      postcode: postcode?.value || ""
    });
  };

  return (
    <form
      onSubmit={handleSubmit}
      style={{
        padding: "25px",
        background: "white",
        borderRadius: "12px",
        boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
        marginBottom: "20px"
      }}
    >
      <h2>Search Properties</h2>

      {/* Property Type */}
      <label>Property Type</label>
      <Select
        options={propertyTypes}
        onChange={setType}
        placeholder="Select property type"
      />

      {/* Price Range */}
      <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
        <TextField
          label="Min Price"
          type="text"
          value={minPrice}
          onChange={(e) => handleNumericInput(e, setMinPrice)}
          fullWidth
        />

        <TextField
          label="Max Price"
          type="text"
          value={maxPrice}
          onChange={(e) => handleNumericInput(e, setMaxPrice)}
          fullWidth
        />
      </div>

      {/* Bedroom Range */}
      <div style={{ display: "flex", gap: "10px", marginTop: "10px" }}>
        <TextField
          label="Min Bedrooms"
          type="text"
          value={minBedrooms}
          onChange={(e) => handleNumericInput(e, setMinBedrooms)}
          fullWidth
        />

        <TextField
          label="Max Bedrooms"
          type="text"
          value={maxBedrooms}
          onChange={(e) => handleNumericInput(e, setMaxBedrooms)}
          fullWidth
        />
      </div>

      {/* Date Added */}
      <label style={{ marginTop: "15px", display: "block" }}>Added After</label>
      <DatePicker
        selected={dateAdded}
        onChange={(date) => setDateAdded(date)}
        placeholderText="Select date"
        dateFormat="yyyy-MM-dd"
      />

      {/* Postcode */}
      <label style={{ marginTop: "15px" }}>Postcode</label>
      <Select
        options={postcodeOptions}
        onChange={setPostcode}
        placeholder="Select postcode"
      />

      {/* Search button */}
      <Button
        type="submit"
        variant="contained"
        color="primary"
        fullWidth
        style={{ marginTop: "20px" }}
      >
        Search
      </Button>
    </form>
  );
};

export default SearchForm;
