// HomePage.js
// ------------------------------------------------------
// This page handles:
// - displaying the search form
// - filtering properties by user criteria
// - showing search results as cards
// - favourites sidebar (add/remove)
// - drag-and-drop support (react-beautiful-dnd)
// ------------------------------------------------------

import React, { useState } from "react";
import SearchForm from "../components/SearchForm/SearchForm";
import PropertyCard from "../components/PropertyCard/PropertyCard";
import propertiesData from "../data/properties.json";
import useFavourites from "../hooks/useFavourites";
import { isAfter } from "date-fns";
import { DragDropContext, Droppable, Draggable } from "react-beautiful-dnd";

const HomePage = () => {
  // Store filtered search results
  const [results, setResults] = useState(propertiesData);

  // Favourites management (custom hook)
  const { favourites, addFavourite, removeFavourite, clearFavourites } = useFavourites();

  // ------------------------------------------------------
  // SEARCH FUNCTION — filters properties by all criteria
  // ------------------------------------------------------
  const handleSearch = (criteria) => {
    let filtered = propertiesData;

    // Filter by type
    if (criteria.type && criteria.type !== "Any") {
      filtered = filtered.filter((p) => p.type === criteria.type);
    }

    // Filter by minimum price
    if (criteria.minPrice) {
      filtered = filtered.filter((p) => p.price >= Number(criteria.minPrice));
    }

    // Filter by maximum price
    if (criteria.maxPrice) {
      filtered = filtered.filter((p) => p.price <= Number(criteria.maxPrice));
    }

    // Filter by bedrooms (min)
    if (criteria.minBedrooms) {
      filtered = filtered.filter((p) => p.bedrooms >= Number(criteria.minBedrooms));
    }

    // Filter by bedrooms (max)
    if (criteria.maxBedrooms) {
      filtered = filtered.filter((p) => p.bedrooms <= Number(criteria.maxBedrooms));
    }

    // Filter by date added
    if (criteria.dateAdded) {
      filtered = filtered.filter((p) =>
        isAfter(new Date(p.dateAdded), criteria.dateAdded)
      );
    }

    // Filter by postcode area
    if (criteria.postcode) {
      filtered = filtered.filter((p) => p.postcode === criteria.postcode);
    }

    setResults(filtered);
  };

  // ------------------------------------------------------
  // DRAG AND DROP FUNCTIONALITY
  // Handles moving items into favourites & removing them
  // ------------------------------------------------------
  const onDragEnd = (result) => {
    if (!result.destination) return;

    // Drag from results → favourites
    if (
      result.source.droppableId === "results" &&
      result.destination.droppableId === "favourites"
    ) {
      const draggedProperty = results[result.source.index];
      addFavourite(draggedProperty);
    }

    // Drag out of favourites → remove
    if (
      result.source.droppableId === "favourites" &&
      result.destination.droppableId !== "favourites"
    ) {
      const draggedFavourite = favourites[result.source.index];
      removeFavourite(draggedFavourite.id);
    }
  };

  return (
    <DragDropContext onDragEnd={onDragEnd}>
      <div className="homepage-layout" style={{ padding: "20px" }}>
        
        {/* ---------------------------- */}
        {/* LEFT: FAVOURITES SIDEBAR    */}
        {/* ---------------------------- */}
        <Droppable droppableId="favourites">
          {(provided) => (
            <div
              className="favourites-sidebar"
              ref={provided.innerRef}
              {...provided.droppableProps}
              style={{
                padding: "15px",
                borderRadius: "12px",
                minHeight: "300px",
                background: "white",
              }}
            >
              <h3>Your Favourites</h3>

              {/* Clear all favourites */}
              {favourites.length > 0 && (
                <button
                  onClick={clearFavourites}
                  className="primary"
                  style={{ marginBottom: "10px", width: "100%" }}
                >
                  Clear All
                </button>
              )}

              {/* Render favourite items */}
              {favourites.map((fav, index) => (
                <Draggable key={fav.id} draggableId={fav.id} index={index}>
                  {(provided) => (
                    <div
                      ref={provided.innerRef}
                      {...provided.draggableProps}
                      {...provided.dragHandleProps}
                      style={{
                        padding: "10px",
                        marginBottom: "10px",
                        background: "white",
                        border: "1px solid #ccc",
                        borderRadius: "8px",
                        ...provided.draggableProps.style
                      }}
                    >
                      {fav.type} — £{fav.price.toLocaleString()}
                    </div>
                  )}
                </Draggable>
              ))}

              {provided.placeholder}
            </div>
          )}
        </Droppable>

        {/* ---------------------------- */}
        {/* RIGHT: SEARCH + RESULTS      */}
        {/* ---------------------------- */}
        <div style={{ flexGrow: 1 }}>
          <SearchForm onSearch={handleSearch} />

          <h2 style={{ marginTop: "30px" }}>
            {results.length} properties found
          </h2>

          <Droppable droppableId="results">
            {(provided) => (
              <div
                className="results-grid"
                ref={provided.innerRef}
                {...provided.droppableProps}
                style={{ marginTop: "20px" }}
              >
                {results.map((p, index) => (
                  <Draggable key={p.id} draggableId={p.id} index={index}>
                    {(provided) => (
                      <div
                        ref={provided.innerRef}
                        {...provided.draggableProps}
                        {...provided.dragHandleProps}
                      >
                        <PropertyCard property={p} />

                        {/* Add to favourites button */}
                        <button
                          className="primary"
                          onClick={() => addFavourite(p)}
                          style={{ marginTop: "10px", width: "100%" }}
                        >
                          Add to Favourites
                        </button>
                      </div>
                    )}
                  </Draggable>
                ))}

                {provided.placeholder}
              </div>
            )}
          </Droppable>

        </div>
      </div>
    </DragDropContext>
  );
};

export default HomePage;
